use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn add(p:impl AsRef<Path>,pins:&mut BTreeMap<String,String>){let p=p.as_ref();pins.insert(p.to_str().unwrap().into(),hash(p));}
fn save(p:impl AsRef<Path>,v:Value){fs::write(p,format!("{}\n",serde_json::to_string_pretty(&v).unwrap())).unwrap()}
fn main(){let root=Path::new("/tmp/zopro-retained-deque-buffers");assert_eq!(read(root.join("perf/result.json"))["status"],"complete");assert_eq!(read(root.join("trace-build/result.json"))["status"],"complete");
let perf=read(root.join("perf-plan.json"));let mut pins:BTreeMap<String,String>=serde_json::from_value(perf["pins"].clone()).unwrap();let artifacts=read(root.join("trace-build/candidate/artifacts.json"));assert_eq!(hash(artifacts["binary"].as_str().unwrap()),artifacts["binary_sha256"].as_str().unwrap());add(artifacts["binary"].as_str().unwrap(),&mut pins);for(p,h)in artifacts["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().into());}
for name in ["prepare-trace.rs","analyze-trace.rs","perf-plan.json","perf/result.json","perf/proof-inventory.json","trace-build-plan.json","trace-build/result.json","trace-build/candidate/artifacts.json","trace-build/libraries/stdout.log","inventory-trace.sh","validate-trace.jq"]{add(root.join(name),&mut pins)}
let mut prior:BTreeSet<String>=serde_json::from_value(perf["prior_proof_sha256"].clone()).unwrap();for(p,h)in read(root.join("perf/proof-inventory.json")).as_object().unwrap(){let actual=root.join("perf").join(p);assert_eq!(hash(&actual),h.as_str().unwrap());add(&actual,&mut pins);if p.ends_with(".proof"){assert!(prior.insert(h.as_str().unwrap().into()));}}
let mut template=read(root.join("all-nine-template.json"));template["prior_proof_sha256"]=json!(prior);save(root.join("trace-template.json"),template.clone());add(root.join("trace-template.json"),&mut pins);
let mut steps=Vec::new();for mode in ["off","on"]{for case in template["cases"].as_array().unwrap(){let shape=case["shape"].as_str().unwrap();let image=case["image"].as_str().unwrap();let stem=Path::new(image).file_stem().unwrap().to_str().unwrap();let name=format!("{mode}-w32-{shape}");let proof=root.join("trace-proofs").join(&name);steps.push(json!({"kind":"command","name":format!("{name}-prove"),"argv":["taskset","-c","0-31",root.join("trace-build/candidate-sdk").to_str().unwrap(),image,case["request"].as_str().unwrap(),"1",proof.join(stem).to_str().unwrap()],"environment":{"RAYON_NUM_THREADS":"32","ZOPRO_CPU_RETAINED_DEQUE_BUFFERS":if mode=="on"{"1"}else{"0"}},"timeout_seconds":600}));steps.push(json!({"kind":"command","name":format!("{name}-verify"),"argv":["/tmp/zopro-gnark-verify/verify","/tmp/zopro-keys",proof.to_str().unwrap(),"/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"],"timeout_seconds":600}));}}
steps.push(json!({"kind":"command","name":"proof-inventory","argv":["bash",root.join("inventory-trace.sh")],"timeout_seconds":30}));steps.push(json!({"kind":"command","name":"validate-inventory","argv":["jq","-n","--slurpfile","inventory",root.join("trace-proof-inventory.json"),"--slurpfile","template",root.join("trace-template.json"),"-f",root.join("validate-trace.jq")],"timeout_seconds":30}));assert_eq!(steps.len(),38);
let mut environment=read(root.join("trace-build-plan.json"))["environment"].clone();environment["RAYON_NUM_THREADS"]=json!("32");save(root.join("trace-input-pins.json"),json!(pins));save(root.join("trace-plan.json"),json!({"version":1,"source_pins":root.join("trace-input-pins.json"),"environment":environment,"steps":steps}));println!("TRACE_FROZEN72SDK18exports,{} prior identities and{} input pins",prior.len(),pins.len());}
